/** Published phenomenological epiretinal models, pinned to pulse2percept 0.11.0.
 * Geometry is generated by the native package, never by display paths. Its
 * BSD-3-Clause license and independent Python reproduction accompany the assets.
 */
export const PERCEPT_REFERENCE_VERSION = 'pulse2percept 0.11.0';
const SCHEMA = 'retinal-axon-reference-v2';
const MODELS = ['axon', 'scoreboard', 'biphasic', 'biphasic-scoreboard'];
const F32 = Math.fround;
const finite = (x, label) => { if (typeof x !== 'number' || !Number.isFinite(x)) throw new Error(`${label} must be finite.`); return x; };

/** Watson Eq. A5; visual x preserved and visual y reversed in retinal basis. */
export function visualToRetinal(xDeg, yDeg) {
  finite(xDeg, 'Visual x'); finite(yDeg, 'Visual y');
  const r = Math.hypot(xDeg, yDeg); if (!r) return { xUm: 0, yUm: 0 };
  const scale = 1000 * (0.268 * r + 3.427e-4 * r * r - 8.3309e-6 * r ** 3) / r;
  return { xUm: xDeg * scale, yUm: -yDeg * scale };
}
/** Watson Eq. A6 is separately fitted; it is not an exact inverse of Eq. A5. */
export function retinalToVisual(xUm, yUm) {
  finite(xUm, 'Retinal x'); finite(yUm, 'Retinal y');
  const r = Math.hypot(xUm, yUm); if (!r) return { xDeg: 0, yDeg: 0 };
  const mm = r / 1000, deg = 3.556 * mm + 0.05993 * mm ** 2 - 0.007358 * mm ** 3 + 3.027e-4 * mm ** 4;
  return { xDeg: xUm * deg / r, yDeg: -yUm * deg / r };
}

// SHA-256 fallback keeps local HTTP previews verifiable when SubtleCrypto is
// unavailable. This hashes public model data; no credentials are involved.
export async function referenceDigest(input) {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  if (globalThis.crypto?.subtle) {
    const hash = new Uint8Array(await globalThis.crypto.subtle.digest('SHA-256', bytes));
    return Array.from(hash, b => b.toString(16).padStart(2, '0')).join('');
  }
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const n = Math.ceil((bytes.length + 9) / 64) * 64, buffer = new Uint8Array(n), words = new Uint32Array(64); buffer.set(bytes); buffer[bytes.length] = 128;
  const view = new DataView(buffer.buffer); view.setUint32(n - 8, Math.floor(bytes.length / 0x20000000)); view.setUint32(n - 4, bytes.length * 8 >>> 0);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < n; off += 64) {
    for (let i = 0; i < 16; i++) words[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) { const x = words[i - 15], y = words[i - 2]; words[i] = (words[i - 16] + (rotr(x,7)^rotr(x,18)^(x>>>3)) + words[i - 7] + (rotr(y,17)^rotr(y,19)^(y>>>10))) >>> 0; }
    let [a,b,c,d,e,f,g,j] = h;
    for (let i = 0; i < 64; i++) { const t1 = (j + (rotr(e,6)^rotr(e,11)^rotr(e,25)) + ((e&f)^((~e)&g)) + K[i] + words[i]) >>> 0; const t2 = ((rotr(a,2)^rotr(a,13)^rotr(a,22)) + ((a&b)^(a&c)^(b&c))) >>> 0; j=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0; }
    [a,b,c,d,e,f,g,j].forEach((v,i) => h[i] = (h[i] + v) >>> 0);
  }
  return h.map(x => x.toString(16).padStart(8,'0')).join('');
}

export function parsePerceptReference(manifest, input) {
  if (!manifest || manifest.schema !== SCHEMA || manifest.referenceVersion !== '0.11.0') throw new Error('Unsupported retinal reference version.');
  const buffer = input instanceof ArrayBuffer ? input : input.buffer.slice(input.byteOffset, input.byteOffset + input.byteLength);
  if (buffer.byteLength !== manifest.byteLength) throw new Error('Retinal reference size mismatch.');
  const little = new Uint8Array(new Uint32Array([1]).buffer)[0] === 1; if (!little) throw new Error('This reference requires a little-endian runtime.');
  const types = { '<f4': Float32Array, '<f8': Float64Array, '<u4': Uint32Array }, arrays = {};
  for (const [name, descriptor] of Object.entries(manifest.arrays)) {
    const Type = types[descriptor.dtype], { offset, length } = descriptor;
    if (!Type || !Number.isInteger(offset) || !Number.isInteger(length) || offset < 0 || length < 0 || offset % Type.BYTES_PER_ELEMENT || offset + length * Type.BYTES_PER_ELEMENT > buffer.byteLength) throw new Error(`Invalid reference array: ${name}.`);
    arrays[name] = new Type(buffer, offset, length);
  }
  const eyes = {};
  for (const eye of ['RE','LE']) {
    const m = manifest.eyes[eye], e = { ...m };
    for (const key of ['xy','arc','offsets','bundleIndex','segmentIndex','d0','gridXY']) { e[key] = arrays[m[key]]; if (!e[key]) throw new Error(`Missing ${eye} ${key} reference.`); }
    if (e.width !== 121 || e.height !== 121 || e.xy.length !== e.segmentCount * 2 || e.arc.length !== e.segmentCount || e.gridXY.length !== 121 * 121 * 2 || e.bundleIndex.length !== 121 * 121 || e.segmentIndex.length !== 121 * 121 || e.d0.length !== 121 * 121 || e.offsets.length !== e.bundleCount + 1 || e.offsets.at(-1) !== e.segmentCount) throw new Error(`Invalid ${eye} geometry dimensions.`);
    eyes[eye] = e;
  }
  return { manifest, eyes, buffer };
}

export async function loadPerceptReference(baseUrl = '/assets/retinal-implant/', fetchFn = fetch) {
  const root = baseUrl.endsWith('/') ? baseUrl : baseUrl + '/';
  const response = await fetchFn(root + 'axon-reference.json'); if (!response.ok) throw new Error(`Reference manifest could not load (${response.status}).`);
  const manifest = await response.json();
  if (manifest.schema !== SCHEMA || manifest.storage?.format !== 'gzip-chunks' || !Array.isArray(manifest.storage.chunks) || manifest.storage.chunks.length > 128 || manifest.byteLength > 16000000) throw new Error('Unsupported reference asset manifest.');
  const chunks = await Promise.all(manifest.storage.chunks.map(async part => {
    if (!/^axon-part-\d{3}\.bin$/.test(part.file) || part.bytes > 65536) throw new Error('Invalid reference chunk.');
    const r = await fetchFn(root + part.file); if (!r.ok) throw new Error(`Reference chunk could not load (${r.status}).`);
    const b = new Uint8Array(await r.arrayBuffer());
    if (b.byteLength !== part.bytes || await referenceDigest(b) !== part.sha256) throw new Error('Reference chunk checksum mismatch.');
    return b;
  }));
  const n = chunks.reduce((s,b) => s + b.length, 0); if (n !== manifest.storage.compressedBytes) throw new Error('Compressed reference length mismatch.');
  const packed = new Uint8Array(n); let off = 0; for (const chunk of chunks) { packed.set(chunk, off); off += chunk.length; }
  return decodePerceptReference(manifest, packed);
}

export async function decodePerceptReference(manifest, packed) {
  if (typeof DecompressionStream === 'undefined') throw new Error('This browser needs support for gzip DecompressionStream to load the reference anatomy.');
  const encoded = new Uint8Array(await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
  if (encoded.length !== manifest.byteLength || encoded.length % 16 || manifest.storage.transform !== 'xor-halves-byte-shuffle-8') throw new Error('Unsupported or invalid reference storage transform.');
  const data = new Uint8Array(encoded.length), words = data.length / 8;
  for (let byte = 0; byte < 8; byte++) for (let i = 0; i < words; i++) data[i * 8 + byte] = encoded[byte * words + i];
  const half = data.length / 2; for (let i = 0; i < half; i++) data[i + half] ^= data[i];
  if (await referenceDigest(data) !== manifest.dataSha256) throw new Error('Reconstructed reference checksum mismatch.');
  return parsePerceptReference(manifest, data);
}

export function biphasicFactors(amplitudeRatio, phaseDurationMs, frequencyHz, rhoUm = 300, lambdaUm = 700) {
  const corrected = amplitudeRatio * (0.054326 + 2.095 * phaseDurationMs);
  return { brightness: 0.1492147 * corrected + 0.0163851 * frequencyHz,
    size: Math.max(1.0812 * corrected - 0.35338, 100 / (rhoUm * rhoUm)),
    streak: Math.max(1.56 - 0.54 * phaseDurationMs ** 0.21, 100 / (lambdaUm * lambdaUm)) };
}

function imageMetrics(brightness, width, xDeg, yDeg, step) {
  let peak = 0, sum = 0, weightedX = 0, weightedY = 0, edge = 0;
  for (let i = 0; i < brightness.length; i++) { const b = brightness[i], r = Math.floor(i/width), c = i%width; peak = Math.max(peak,b);sum+=b;weightedX+=b*xDeg[c];weightedY+=b*yDeg[r]; if (!r || !c || r===width-1 || c===width-1) edge=Math.max(edge,b); }
  let n=0,cx=0,cy=0,xx=0,yy=0,xy=0,touches=false;
  if (peak>0) for(let i=0;i<brightness.length;i++) if(brightness[i]>=peak*.5) { const r=Math.floor(i/width),c=i%width,x=xDeg[c],y=yDeg[r];n++;cx+=x;cy+=y;xx+=x*x;yy+=y*y;xy+=x*y;if(!r||!c||r===width-1||c===width-1)touches=true; }
  let elongation=null;
  if(n){cx/=n;cy/=n;xx=xx/n-cx*cx;yy=yy/n-cy*cy;xy=xy/n-cx*cy;const disc=Math.sqrt(Math.max(0,(xx-yy)**2+4*xy*xy)),major=(xx+yy+disc)/2,minor=(xx+yy-disc)/2;if(minor>1e-14)elongation=Math.sqrt(major/minor);}
  return { peakBrightness: peak, integratedBrightness: sum*step*step, supportAreaDeg2:n*step*step,
    equivalentDiameterDeg: n?Math.sqrt(4*n*step*step/Math.PI):0,supportElongation:elongation,
    intensityCentroidDeg:sum?[weightedX/sum,weightedY/sum]:null,supportCentroidDeg:n?[cx,cy]:null,
    touchesBoundary:touches,edgePeakFraction:peak?edge/peak:0,appreciableTailAtBoundary:peak>0&&edge/peak>=.01 };
}

/** One representative spatial percept; not a membrane, spike or acuity model. */
export function predictPercept(reference, options = {}) {
  const { electrodes = [], eye = 'RE', model = 'axon', rhoUm = 300, lambdaUm = 700, frequencyHz = 20, phaseDurationMs = .45, gridStepDeg = .5 } = options;
  if (!reference?.eyes?.[eye]) throw new Error('Eye must be RE or LE with loaded reference anatomy.');
  if (!MODELS.includes(model)) throw new Error(`Unsupported percept model: ${model}.`);
  if (![.5,.25].includes(gridStepDeg)) throw new Error('Visual grid step must be 0.5 or 0.25 degrees.');
  if (finite(rhoUm,'rho')<=0 || finite(lambdaUm,'lambda')<10 || finite(frequencyHz,'Frequency')<0 || finite(phaseDurationMs,'Phase duration')<=0) throw new Error('Require positive rho and phase duration, lambda >=10 and frequency >=0.');
  if (!Array.isArray(electrodes) || electrodes.length > 1024) throw new Error('Supply at most 1024 electrode records.');
  const biphasic=model.startsWith('biphasic'), axonal=model==='axon'||model==='biphasic', g=reference.eyes[eye];
  const width=Math.round(30/gridStepDeg)+1,stride=gridStepDeg/.25;
  const xDeg=Float64Array.from({length:width},(_,i)=>-15+i*gridStepDeg),yDeg=Float64Array.from({length:width},(_,i)=>15-i*gridStepDeg);
  const brightness=new Float32Array(width*width),effects=[],active=[];
  const cutoff=-2*rhoUm*rhoUm*Math.log(1e-8);
  for(const e of electrodes){
    const x=F32(finite(e.xUm,'Electrode x')),y=F32(finite(e.yUm,'Electrode y')),amp=finite(e.amplitudeUa,'Electrode amplitude');
    if(amp<0)throw new Error('Percept amplitude must be a nonnegative cathodic magnitude.');
    const threshold=e.thresholdUa ?? 50;
    if(biphasic && finite(threshold,'Detection threshold')<=0)throw new Error('Biphasic detection threshold must be positive.');
    const f=biphasic?biphasicFactors(amp/threshold,phaseDurationMs,frequencyHz,rhoUm,lambdaUm):{brightness:amp,size:1,streak:1};
    const on=amp>0&&(!biphasic||frequencyHz>0);
    effects.push({id:e.id,amplitudeUa:amp,thresholdUa:threshold,...f,effectiveRhoUm:rhoUm*Math.sqrt(f.size),effectiveLambdaUm:lambdaUm*Math.sqrt(f.streak),active:on});
    if(on)active.push({x,y,drive:f.brightness,size:f.size,streak:f.streak,r2:cutoff*f.size,neg:-1/(2*rhoUm*rhoUm*f.size)});
  }
  if(active.length){
    if(axonal){
      // For this API every electrode shares phase duration, hence a common
      // streak factor. Factoring it out preserves max-after-sum semantics.
      const combined=new Float64Array(g.segmentCount);
      for(const e of active){const radius=Math.sqrt(e.r2);for(let k=0;k<g.segmentCount;k++){const dx=g.xy[2*k]-e.x;if(Math.abs(dx)>radius)continue;const dy=g.xy[2*k+1]-e.y,r2=dx*dx+dy*dy;if(r2<=e.r2)combined[k]+=e.drive*Math.exp(r2*e.neg);}}
      const maxDistance=Math.sqrt(-2*lambdaUm*lambdaUm*Math.log(1e-3)), invStreak=1/active[0].streak;
      for(let row=0;row<width;row++)for(let col=0;col<width;col++){
        const p=row*stride*121+col*stride,end=g.segmentIndex[p],start=g.offsets[g.bundleIndex[p]],somaArc=g.d0[p]+g.arc[end];let best=0;
        for(let k=end;k>=start;k--){const distance=somaArc-g.arc[k];if(distance>=maxDistance)break;if(!combined[k])continue;
          const nativeSensitivity=F32(Math.exp(-distance*distance/(2*lambdaUm*lambdaUm)));
          const value=combined[k]*(biphasic?Math.exp(Math.log(nativeSensitivity)*invStreak):nativeSensitivity);if(value>best)best=value;
        }
        brightness[row*width+col]=best;
      }
    }else{
      for(let row=0;row<width;row++)for(let col=0;col<width;col++){
        const p=row*stride*121+col*stride,x=g.gridXY[2*p],y=g.gridXY[2*p+1];let value=0;
        for(const e of active){const dx=x-e.x,dy=y-e.y,r2=dx*dx+dy*dy;if(r2<=e.r2)value+=e.drive*Math.exp(r2*e.neg);}
        brightness[row*width+col]=value;
      }
    }
  }
  const centralSpacingUm=Math.abs(visualToRetinal(gridStepDeg,0).xUm),minEffectiveRhoUm=active.length?Math.min(...active.map(e=>rhoUm*Math.sqrt(e.size))):null;
  const undersampled=minEffectiveRhoUm!==null&&minEffectiveRhoUm<centralSpacingUm;
  const metadata={referenceVersion:PERCEPT_REFERENCE_VERSION,coordinateFrame:'Visual-field degrees; +y superior; row zero +15 degrees',brightnessUnits:biphasic?'Empirical model units':'Spatial drive model units (amplitude in µA)',
    formulation:'Sum electrode drive at each axon segment, then maximum along each soma-to-disc path.',
    temporalScope:biphasic?'One representative simultaneous zero-delay cathodic-first pulse-train image; no within-train dynamics or interphase-gap effect.':'Static spatial response; pulse timing is not modeled.',
    geometryScope:'Population-average Jansonius anatomy; rho and lambda are fitted percept parameters independent of physical gap, diameter or conductivity.',
    sampling:{centralSpacingUm,minEffectiveRhoUm,spreadBelowCentralGridInterval:undersampled,narrowestGaussianFwhmSamples:minEffectiveRhoUm===null?null:2*Math.sqrt(2*Math.log(2))*minEffectiveRhoUm/centralSpacingUm,warning:undersampled?'The narrowest effective percept spread is smaller than one central grid interval. Use the finer visual grid and inspect sampling sensitivity.':null,interpretation:'Conservative sampling prompt, not an accuracy bound.'}};
  return {width,height:width,xDeg,yDeg,brightness,metrics:imageMetrics(brightness,width,xDeg,yDeg,gridStepDeg),electrodeEffects:effects,metadata,reference:PERCEPT_REFERENCE_VERSION,model,eye};
}
